{
  "investigate": [
    {
      "tool": "sql",
      "query": "SELECT service, used_mb, quota_mb FROM storage WHERE service IN ('worker', 'sync-job')",
      "why": "Check disk usage for worker and sync-job to confirm resource exhaustion"
    },
    {
      "tool": "logs",
      "service": "payment-provider",
      "level": "ERROR",
      "contains": "503",
      "why": "Verify if payment-provider is experiencing outages externally"
    }
  ],
  "hypotheses": [
    {
      "service": "worker",
      "kind": "resource_exhaustion",
      "mechanism": "Disk quota exceeded causing invoice file write failures and dead letters",
      "supporting": ["E14", "E15", "E3", "E7"],
      "refuting": ["E21"],
      "explains": ["M3_dead_letters", "E3", "E7", "E14", "E15"],
      "repair_plan": [
        {
          "action": "restart_service",
          "params": {
            "service": "worker"
          }
        }
      ]
    },
    {
      "service": "payment-provider",
      "kind": "external_dependency",
      "mechanism": "External payment provider returning 503 errors causing payment failures",
      "supporting": ["E13", "E4", "E11", "E10"],
      "refuting": ["E19"],
      "explains": ["I7_payments_succeed", "M2_error_burst", "E1", "E4", "E11", "E13"],
      "repair_plan": []
    }
  ],
  "summary": "Disk exhaustion in worker and external payment provider failures are causing dead letters and payment errors."
}
